{
  "steps": [
    {
      "title": "დაკეტე წყალი",
      "text": "მოატრიალე ონკანი საათის ისრის მიმართულებით ბოლომდე. შემდეგ მეორეც დაკეტე.",
      "focus": ["p2", "p3"],
      "avoid": [],
      "markers": [],
      "arrows": [
        {"part": "p2", "type": "rotate", "dir": "cw"},
        {"part": "p3", "type": "rotate", "dir": "cw"}
      ],
      "tools": [],
      "warn": "დაკეტე ნაზად; თუ სარქველი გაჭედილია, ძალას ნუ დაატან."
    },
    {
      "title": "ჩადგი ვედრო სიფონის ქვეშ",
      "text": "სიფონში წყალი დგას. გახსნისას ჩამოიღვრება, ამიტომ ვედრო ან ღრმა თასი პირდაპირ მის ქვეშ დადგი.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["ვედრო ან ღრმა თასი"],
      "warn": "ვედრო ან თასი ფოტოზე არ ჩანს და მინიჭებული ID არ აქვს. დამფარავი ფორმა დასადგმელ ნივთად ვერ იდენტიფიცირდება."
    },
    {
      "title": "მოუშვი ქანჩი",
      "text": "ეს ქანჩი ჟონავს. ხელით მოუშვი საათის ისრის საწინააღმდეგოდ. პლასტმასისაა, გასაღები არ დაგჭირდება.",
      "focus": ["p4"],
      "avoid": ["p1"],
      "markers": [
        {"part": "p4", "label": "სავარაუდოდ ჟონავს", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "არჩეულია p4: მარჯვენა ჰორიზონტალურ შეერთებაზე ქანჩის ქვემოთ ჩანს ჩამოკიდებული წვეთი და სველი კვალი. ეს გაჟონვის ყველაზე სავარაუდო ადგილია, თუმცა წყლის ზუსტი წყარო მხოლოდ ფოტოთი ვერ დასტურდება."
    },
    {
      "title": "შეამოწმე შუასადები",
      "text": "მოხსენი სიფონი და ნახე ქანჩის შიგნით რეზინის რგოლი. თუ დაბზარულია ან გვერდზეა გადაწეული, შეცვალე. ზომა: 40 მმ.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["შესაბამისი ზომის ახალი შუასადები"],
      "warn": "ქანჩის შიდა შუასადები უხილავია და ID არ აქვს; სიფონსაც ცალკე ID არ აქვს და ნაწილობრივ დაფარულია. 40 მმ მოცემულია ინსტრუქციაში, მაგრამ ფოტოთი არ დასტურდება — შეცვლამდე გადაამოწმე ზომა."
    },
    {
      "title": "მოუჭირე და შეამოწმე",
      "text": "ხელით მოუჭირე ბოლომდე, შემდეგ კიდევ მეოთხედი ბრუნი. გახსენი წყალი და ერთი წუთი დააკვირდი.",
      "focus": ["p4", "p2", "p3"],
      "avoid": ["p1"],
      "markers": [
        {"part": "p4", "label": "შეამოწმე გაჟონვა", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "cw"},
        {"part": "p2", "type": "rotate", "dir": "ccw"},
        {"part": "p3", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "იგულისხმება სავარაუდოდ ჟონავი p4. პლასტმასის ქანჩი არ გადაჭიმო: დამატებითი მეოთხედი ბრუნი მხოლოდ მაშინ გააკეთე, თუ მწარმოებლის მითითება უშვებს. სარქვლების გახსნის შემდეგ ნიჟარის ონკანიც გაუშვი; ის ფოტოზე არ ჩანს."
    }
  ],
  "unknown_parts": [
    "ვედრო ან ღრმა თასი — არ ჩანს და ID არ აქვს.",
    "სიფონი — ნაწილობრივ დაფარულია და ცალკე ID არ აქვს.",
    "ქანჩის შიდა რეზინის შუასადები — უხილავია და ID არ აქვს.",
    "ნიჟარის ონკანი — ფოტოზე არ ჩანს და ID არ აქვს."
  ]
}
